HIST_DATA["special-british-india"] = {"country": "Pakistan", "id": "british-india", "kind": "topic", "name_sd": "برطانوي ھندستان", "name_ur": "برطانوی ہندوستان", "region": "Pakistan", "sections_sd": [{"heading": "تعارف", "text": "برطانوي راڄ 1858 کان 1947 تائين برصغير تي برطانوي تاج جي سڌي حڪومت هيو. اهو 1857 جي جنگ آزاديءَ کان پوءِ شروع ٿيو، جڏهن ايسٽ انڊيا ڪمپني کان انتظام تاج کي منتقل ٿيو. 1947 ۾ برطانوي هندستان جي ورهاڱي سان هندستان ۽ پاڪستان ٻه آزاد رياستون بڻيون."}, {"heading": "ڪمپني دور کان تاج جي حڪومت تائين", "text": "ايسٽ انڊيا ڪمپني 1600 ۾ واپار لاءِ آئي ۽ 1757 ۾ پلاسيءَ جي جنگ کان پوءِ سياسي طاقت بڻي. 1857 جي جنگ آزاديءَ کان پوءِ 1858 جي گورنمينٽ آف انڊيا ايڪٽ سان تاج سڌو انتظام سنڀاليو. 1876 ۾ ملڪه وڪٽوريا هندستان جي قيصر اعلان ڪئي وئي، جنهن جو اعلان 1877 جي دهلي درٻار ۾ ٿيو."}, {"heading": "انتظام ۽ سڌارا", "text": "برطانوي راڄ ۾ گاديءَ جو هنڌ ڪلڪتو هيو، جيڪو 1911 ۾ دهلي منتقل ٿيو. هن دور ۾ ريلوي، ٽپال ۽ تعليمي ادارا قائم ٿيا، پر معيشت نوآباديائي مفادن لاءِ هلائي وئي. 1909، 1919 ۽ 1935 جي سڌارن سان هندستانين کي محدود نمائندگي ملي، پر اصل اقتدار وائسراءِ وٽ رهيو."}, {"heading": "خاتمو", "text": "ٻئي مهاڀاري جنگ کان پوءِ آزاديءَ جي تحريڪ زور ورتو. 3 جون 1947 جي منصوبي ۽ 18 جولاءِ 1947 جي انڊين انڊيپينڊنس ايڪٽ سان برطانوي حڪومت ختم ٿي ۽ 14-15 آگسٽ 1947 تي برصغير هندستان ۽ پاڪستان ۾ ورهائجي ويو."}], "sections_ur": [{"heading": "تعارف", "text": "برطانوی راج 1858 سے 1947 تک برصغیر پر برطانوی تاج کی براہ راست حکومت تھا۔ یہ 1857 کی جنگ آزادی کے بعد شروع ہوا، جب ایسٹ انڈیا کمپنی سے انتظام تاج کو منتقل ہوا۔ 1947 میں برطانوی ہندوستان کی تقسیم سے ہندوستان اور پاکستان دو آزاد ریاستیں بنے۔"}, {"heading": "کمپنی دور سے تاج کی حکومت تک", "text": "ایسٹ انڈیا کمپنی 1600 میں تجارت کے لیے آئی اور 1757 میں پلاسی کی جنگ کے بعد سیاسی طاقت بنی۔ 1857 کی جنگ آزادی کے بعد 1858 کے گورنمنٹ آف انڈیا ایکٹ سے تاج نے براہ راست انتظام سنبھالا۔ 1876 میں ملکہ وکٹوریہ ہندوستان کی قیصر اعلان کی گئیں، جس کا اعلان 1877 کے دہلی دربار میں ہوا۔"}, {"heading": "انتظام اور اصلاحات", "text": "برطانوی راج میں دارالحکومت کلکتہ تھا، جو 1911 میں دہلی منتقل ہوا۔ اس دور میں ریلوے، ڈاک اور تعلیمی ادارے قائم ہوئے، مگر معیشت نوآبادیاتی مفادات کے لیے چلائی گئی۔ 1909، 1919 اور 1935 کی اصلاحات سے ہندوستانیوں کو محدود نمائندگی ملی، مگر اصل اقتدار وائسرائے کے پاس رہا۔"}, {"heading": "خاتمہ", "text": "دوسری عالمی جنگ کے بعد آزادی کی تحریک نے زور پکڑا۔ 3 جون 1947 کے منصوبے اور 18 جولائی 1947 کے انڈین انڈیپینڈنس ایکٹ سے برطانوی حکومت ختم ہوئی اور 14-15 اگست 1947 کو برصغیر ہندوستان اور پاکستان میں بٹ گیا۔"}], "sources": [{"title": "British Raj — Wikipedia", "url": "https://en.wikipedia.org/wiki/British_Raj_in_India"}, {"title": "Constitutional Development under Crown Rule — GKToday", "url": "https://www.gktoday.in/constitutional-development-under-crown-rule/"}], "summary_sd": "برطانوي راڄ (1858-1947) برصغير تي برطانوي تاج جي سڌي حڪومت هيو، جيڪو 1857 جي جنگ کان پوءِ قائم ٿيو. هن دور ۾ جديد انتظامي ڍانچو ته ٺهيو، پر اقتدار مڪمل طور انگريزن وٽ رهيو. 1947 ۾ آزادي ۽ ورهاڱي سان هن دور جو خاتمو ٿيو.", "summary_ur": "برطانوی راج (1858-1947) برصغیر پر برطانوی تاج کی براہ راست حکومت تھا، جو 1857 کی جنگ کے بعد قائم ہوا۔ اس دور میں جدید انتظامی ڈھانچہ تو بنا، مگر اقتدار مکمل طور پر انگریزوں کے پاس رہا۔ 1947 میں آزادی اور تقسیم سے اس دور کا خاتمہ ہوا۔", "timeline": [{"era": "1757ء", "text_sd": "پلاسيءَ جي جنگ؛ ڪمپنيءَ جي سياسي طاقت جي شروعات.", "text_ur": "پلاسی کی جنگ؛ کمپنی کی سیاسی طاقت کی شروعات۔"}, {"era": "1857-1858ء", "text_sd": "جنگ آزادي؛ تاج جي سڌي حڪومت جو آغاز.", "text_ur": "جنگ آزادی؛ تاج کی براہ راست حکومت کا آغاز۔"}, {"era": "1877ء", "text_sd": "دهلي درٻار ۾ ملڪه وڪٽوريا قيصر هندستان قرار.", "text_ur": "دہلی دربار میں ملکہ وکٹوریہ قیصر ہندوستان قرار۔"}, {"era": "1911ء", "text_sd": "گاديءَ جو هنڌ ڪلڪتي کان دهلي منتقل ٿيو.", "text_ur": "دارالحکومت کلکتے سے دہلی منتقل ہوا۔"}, {"era": "1947ء", "text_sd": "آزادي ۽ ورهاڱو؛ برطانوي راڄ جو خاتمو.", "text_ur": "آزادی اور تقسیم؛ برطانوی راج کا خاتمہ۔"}]};
HIST_DATA["special-freedom-movement"] = {"country": "Pakistan", "id": "freedom-movement", "kind": "topic", "name_sd": "آزاديءَ جي تحريک", "name_ur": "تحریک آزادی", "region": "Pakistan", "sections_sd": [{"heading": "تعارف", "text": "آزاديءَ جي تحريک برطانوي راڄ کان آزادي حاصل ڪرڻ لاءِ هلندڙ سياسي جدوجهد هئي، جيڪا 1857 جي جنگ کان 1947 ۾ آزادي تائين هلي. هن ۾ هندو ۽ مسلمان ٻنهي اڳواڻن حصو ورتو، جيتوڻيڪ آخر ۾ مسلمانن پنهنجي الڳ سياسي پليٽ فارم تان جدوجهد ڪئي، جيڪا تحريک پاڪستان سڏائي."}, {"heading": "1857 جي جنگ آزادي", "text": "10 مئي 1857 تي ميرٺ ۾ سپاهين بغاوت ڪئي، جيڪا اتر هندستان ۾ پکڙجي وئي. بهادر شاهه ظفر کي علامتي اڳواڻ بڻايو ويو. انگريزن بغاوت کي ڪچلي ڇڏيو، مغل سلطنت جو خاتمو ٿيو ۽ 1858 ۾ تاج سڌو انتظام سنڀاليو. مسلمانن هن جنگ ۾ وڏو نقصان ڀوڳيو."}, {"heading": "سياسي تنظيمون", "text": "1885 ۾ انڊين نيشنل ڪانگريس قائم ٿي. مسلمانن پنهنجي حقن لاءِ 1906 ۾ ڍاڪا ۾ آل انڊيا مسلم ليگ قائم ڪئي. 1916 جو لکنؤ معاهدو هندو-مسلم اتحاد جي ڪوشش هئي. 1919-1922 جي خلافت ۽ عدم تعاون واري تحريڪ ۾ گانڌي ۽ علي ڀائر گڏجي انگريزن خلاف اٿيا."}, {"heading": "آخري ڏهاڪا", "text": "1930 ۾ سول نافرماني، 1929 ۾ لاهور ڪانگريس ۾ مڪمل آزاديءَ جو مطالبو ۽ 1942 ۾ هندستان ڇڏيو تحريڪ آزاديءَ جي جدوجهد جا اهم مرحلا هئا. ٻئي مهاڀاري جنگ کان پوءِ انگريز ڪمزور ٿيا ۽ آخرڪار 1947 ۾ اقتدار هندستان ۽ پاڪستان کي منتقل ٿيو."}], "sections_ur": [{"heading": "تعارف", "text": "تحریک آزادی برطانوی راج سے آزادی حاصل کرنے کے لیے چلنے والی سیاسی جدوجہد تھی، جو 1857 کی جنگ سے 1947 میں آزادی تک چلی۔ اس میں ہندو اور مسلمان دونوں رہنماؤں نے حصہ لیا، اگرچہ آخر میں مسلمانوں نے اپنے الگ سیاسی پلیٹ فارم سے جدوجہد کی، جو تحریک پاکستان کہلائی۔"}, {"heading": "1857 کی جنگ آزادی", "text": "10 مئی 1857 کو میرٹھ میں سپاہیوں نے بغاوت کی، جو شمالی ہندوستان میں پھیل گئی۔ بہادر شاہ ظفر کو علامتی رہنما بنایا گیا۔ انگریزوں نے بغاوت کچل دی، مغلیہ سلطنت کا خاتمہ ہوا اور 1858 میں تاج نے براہ راست انتظام سنبھالا۔ مسلمانوں نے اس جنگ میں بڑا نقصان اٹھایا۔"}, {"heading": "سیاسی تنظیمیں", "text": "1885 میں انڈین نیشنل کانگریس قائم ہوئی۔ مسلمانوں نے اپنے حقوق کے لیے 1906 میں ڈھاکہ میں آل انڈیا مسلم لیگ قائم کی۔ 1916 کا لکھنؤ معاہدہ ہندو۔مسلم اتحاد کی کوشش تھی۔ 1919-1922 کی خلافت اور عدم تعاون کی تحریک میں گاندھی اور علی برادران مل کر انگریزوں کے خلاف اٹھے۔"}, {"heading": "آخری عشرے", "text": "1930 میں سول نافرمانی، 1929 میں لاہور کانگریس میں مکمل آزادی کا مطالبہ اور 1942 میں ہندوستان چھوڑو تحریک آزادی کی جدوجہد کے اہم مراحل تھے۔ دوسری عالمی جنگ کے بعد انگریز کمزور ہوئے اور آخرکار 1947 میں اقتدار ہندوستان اور پاکستان کو منتقل ہوا۔"}], "sources": [{"title": "Pakistan Movement timeline — Wikipedia", "url": "https://en.wikipedia.org/wiki/?title=Pakistan_Movement&oldid=972288938"}, {"title": "Key Events in Pakistan's History — Scribd (timeline document)", "url": "https://www.scribd.com/document/485283239/KEY-YEARS-IN-PAKISTAN-HISTORY"}], "summary_sd": "آزاديءَ جي تحريک 1857 جي جنگ کان شروع ٿي ۽ 1947 ۾ آزاديءَ تي ختم ٿي. هن ۾ ڪانگريس، مسلم ليگ، خلافت تحريڪ ۽ سول نافرماني جهڙا مرحلا آيا. آخر ۾ مسلمانن جي الڳ جدوجهد تحريک پاڪستان جي صورت ۾ ڪامياب ٿي.", "summary_ur": "تحریک آزادی 1857 کی جنگ سے شروع ہوئی اور 1947 میں آزادی پر ختم ہوئی۔ اس میں کانگریس، مسلم لیگ، خلافت تحریک اور سول نافرمانی جیسے مراحل آئے۔ آخر میں مسلمانوں کی الگ جدوجہد تحریک پاکستان کی صورت میں کامیاب ہوئی۔", "timeline": [{"era": "1857ء", "text_sd": "جنگ آزادي؛ مغل سلطنت جو خاتمو.", "text_ur": "جنگ آزادی؛ مغلیہ سلطنت کا خاتمہ۔"}, {"era": "1885ء", "text_sd": "انڊين نيشنل ڪانگريس جو قيام.", "text_ur": "انڈین نیشنل کانگریس کا قیام۔"}, {"era": "1906ء", "text_sd": "آل انڊيا مسلم ليگ جو قيام (ڍاڪا).", "text_ur": "آل انڈیا مسلم لیگ کا قیام (ڈھاکہ)۔"}, {"era": "1919-1922ء", "text_sd": "خلافت ۽ عدم تعاون واري تحريک.", "text_ur": "خلافت اور عدم تعاون کی تحریک۔"}, {"era": "1942ء", "text_sd": "هندستان ڇڏيو تحريک.", "text_ur": "ہندوستان چھوڑو تحریک۔"}, {"era": "1947ء", "text_sd": "آزادي؛ هندستان ۽ پاڪستان جو قيام.", "text_ur": "آزادی؛ ہندوستان اور پاکستان کا قیام۔"}]};
HIST_DATA["special-pakistan-movement"] = {"country": "Pakistan", "id": "pakistan-movement", "kind": "topic", "name_sd": "پاڪستان تحريک", "name_ur": "تحریک پاکستان", "region": "Pakistan", "sections_sd": [{"heading": "پس منظر", "text": "تحريک پاڪستان برصغير جي مسلمانن جي الڳ وطن لاءِ سياسي جدوجهد هئي. ان جو بنياد 1906 ۾ مسلم ليگ جي قيام سان پيو. سر سيد احمد خان جي تعليمي تحريک ۽ علامه اقبال جي فڪر هن تحريک جي فڪري بنياد ٺاهيا. قائداعظم محمد علي جناح 1913 ۾ مسلم ليگ ۾ شامل ٿيا ۽ پوءِ هن تحريک جا اڻٿڪ اڳواڻ بڻيا."}, {"heading": "اهم واقعا", "text": "1930 ۾ علامه اقبال الاه آباد خطبي ۾ اتر-اولهه هندستان ۾ مسلم رياست جو تصور پيش ڪيو. 1933 ۾ چوڌري رحمت علي پنهنجي مشهور پمفليٽ ۾ پاڪستان جو نالو تجويز ڪيو. 23 مارچ 1940 تي لاهور ۾ قرارداد پاڪستان منظور ٿي، جنهن ۾ مسلم اڪثريتي علائقن ۾ آزاد رياستن جو مطالبو ڪيو ويو."}, {"heading": "آخري مرحلو (1942-1947)", "text": "1942 جي ڪرپس مشن جي ناڪامي، 1944 ۾ گانڌي-جناح ڳالهيون، 1945 جي شملا ڪانفرنس ۽ 1946 جي ڪيبنٽ مشن کان پوءِ 16 آگسٽ 1946 تي سڌي ڪارروائي جو ڏينهن ٿيو. آخرڪار 3 جون 1947 جي منصوبي تحت ورهاڱو طئي ٿيو ۽ 14 آگسٽ 1947 تي پاڪستان هڪ آزاد رياست طور وجود ۾ آيو."}, {"heading": "اهم شخصيتون", "text": "قائداعظم محمد علي جناح هن تحريک جا قائد هئا، علامه اقبال فڪري رهنما، لياقت علي خان قائداعظم جا ساڄي هٿ، ۽ فاطمه جناح، مولانا محمد علي جوهر ۽ چوڌري رحمت علي ٻيا اهم نالا آهن. انهن جي گڏيل جدوجهد سان مسلمانن کي الڳ وطن مليو."}], "sections_ur": [{"heading": "پس منظر", "text": "تحریک پاکستان برصغیر کے مسلمانوں کے الگ وطن کے لیے سیاسی جدوجہد تھی۔ اس کی بنیاد 1906 میں مسلم لیگ کے قیام سے پڑی۔ سر سید احمد خان کی تعلیمی تحریک اور علامہ اقبال کے فکر نے اس تحریک کی فکری بنیاد بنائی۔ قائداعظم محمد علی جناح 1913 میں مسلم لیگ میں شامل ہوئے اور پھر اس تحریک کے اٹل رہنما بنے۔"}, {"heading": "اہم واقعات", "text": "1930 میں علامہ اقبال نے الہ آباد خطبے میں شمال۔مغربی ہندوستان میں مسلم ریاست کا تصور پیش کیا۔ 1933 میں چوہدری رحمت علی نے اپنے مشہور پمفلٹ میں پاکستان کا نام تجویز کیا۔ 23 مارچ 1940 کو لاہور میں قرارداد پاکستان منظور ہوئی، جس میں مسلم اکثریتی علاقوں میں آزاد ریاستوں کا مطالبہ کیا گیا۔"}, {"heading": "آخری مرحلہ (1942-1947)", "text": "1942 کے کرپس مشن کی ناکامی، 1944 میں گاندھی۔جناح مذاکرات، 1945 کی شملہ کانفرنس اور 1946 کے کیبنٹ مشن کے بعد 16 اگست 1946 کو یوم راست اقدام ہوا۔ آخرکار 3 جون 1947 کے منصوبے کے تحت تقسیم طے ہوئی اور 14 اگست 1947 کو پاکستان ایک آزاد ریاست کے طور پر وجود میں آیا۔"}, {"heading": "اہم شخصیات", "text": "قائداعظم محمد علی جناح اس تحریک کے قائد تھے، علامہ اقبال فکری رہنما، لیاقت علی خان قائداعظم کے دست راست، اور فاطمہ جناح، مولانا محمد علی جوہر اور چوہدری رحمت علی دیگر اہم نام ہیں۔ ان کی مشترکہ جدوجہد سے مسلمانوں کو الگ وطن ملا۔"}], "sources": [{"title": "Pakistan Movement — Simple Wikipedia (timeline)", "url": "https://simple.wikipedia.org/wiki/Pakistan_Movement"}, {"title": "Pakistan Movement — Wikipedia (detailed timeline)", "url": "https://en.wikipedia.org/wiki/?title=Pakistan_Movement&oldid=972288938"}], "summary_sd": "تحريک پاڪستان مسلمانن جي الڳ وطن لاءِ 1906 کان 1947 تائين هلندڙ سياسي جدوجهد هئي. اقبال جي تصور، 1940 جي قرارداد پاڪستان ۽ قائداعظم جي قيادت سان هيءَ تحريک 14 آگسٽ 1947 تي پاڪستان جي قيام تي ڪامياب ٿي.", "summary_ur": "تحریک پاکستان مسلمانوں کے الگ وطن کے لیے 1906 سے 1947 تک چلنے والی سیاسی جدوجہد تھی۔ اقبال کے تصور، 1940 کی قرارداد پاکستان اور قائداعظم کی قیادت سے یہ تحریک 14 اگست 1947 کو پاکستان کے قیام پر کامیاب ہوئی۔", "timeline": [{"era": "1906ء", "text_sd": "مسلم ليگ جو قيام (ڍاڪا).", "text_ur": "مسلم لیگ کا قیام (ڈھاکہ)۔"}, {"era": "1930ء", "text_sd": "علامه اقبال جو الاه آباد خطبو؛ الڳ مسلم رياست جو تصور.", "text_ur": "علامہ اقبال کا الہ آباد خطبہ؛ الگ مسلم ریاست کا تصور۔"}, {"era": "1940ء", "text_sd": "23 مارچ: لاهور ۾ قرارداد پاڪستان منظور.", "text_ur": "23 مارچ: لاہور میں قرارداد پاکستان منظور۔"}, {"era": "1946ء", "text_sd": "ڪيبنٽ مشن؛ 16 آگسٽ تي سڌي ڪارروائي جو ڏينهن.", "text_ur": "کیبنٹ مشن؛ 16 اگست کو یوم راست اقدام۔"}, {"era": "1947ء", "text_sd": "3 جون جو منصوبو؛ 14 آگسٽ تي پاڪستان جو قيام.", "text_ur": "3 جون کا منصوبہ؛ 14 اگست کو پاکستان کا قیام۔"}]};
HIST_DATA["special-partition-1947"] = {"country": "Pakistan", "id": "partition-1947", "kind": "topic", "name_sd": "ورهاڱو 1947", "name_ur": "تقسیم ہند 1947", "region": "Pakistan", "sections_sd": [{"heading": "تعارف", "text": "1947 ۾ برطانوي هندستان جي ورهاڱي سان هندستان ۽ پاڪستان ٻه آزاد رياستون بڻيون. 3 جون 1947 جي منصوبي ۽ 18 جولاءِ جي انڊين انڊيپينڊنس ايڪٽ تحت اقتدار منتقل ٿيو. پاڪستان 14 آگسٽ 1947 تي وجود ۾ آيو، جڏهن ته هندستان 15 آگسٽ تي آزاد ٿيو."}, {"heading": "ريڊڪلف لائين", "text": "پنجاب ۽ بنگال جي حد بندي لاءِ سر سائرل ريڊڪلف جي صدارت ۾ بائونڊري ڪميشن قائم ڪيا ويا. ريڊڪلف، جيڪو اڳ ڪڏهن هندستان نه آيو هيو، صرف پنجن هفتن ۾ حدون ٺاهيون، جن جو اعلان 17 آگسٽ 1947 تي ٿيو. هن لائين مسلم اڪثريتي علائقا پاڪستان ۽ هندو اڪثريتي علائقا هندستان کي ڏنا."}, {"heading": "لڏپلاڻ ۽ تشدد", "text": "ورهاڱي سان تاريخ جي سڀ کان وڏي لڏپلاڻ ٿي: اندازاً هڪ کان ڏيڍ ڪروڙ ماڻهو سرحدون پار ڪيا. 1951 جي آدمشماري موجب 72 لک کان وڌيڪ مسلمان هندستان کان پاڪستان آيا ۽ ايترائي هندو ۽ سک پاڪستان کان هندستان ويا. فرقيوار تشدد ۾ مرڻ وارن جو انگ عالمن ۾ اختلافي آهي؛ اندازا پنج لک کان ويهن لکن تائين آهن."}, {"heading": "نتيجا", "text": "ورهاڱي سان ڪشمير جو مسئلو پيدا ٿيو، جنهن تي 1947-48 ۾ پهرين پاڪ-هند جنگ ٿي. پنجاب جو آبپاشي نظام ورهائجي ويو، جنهن کي بعد ۾ 1960 جي سنڌ طاس معاهدي سان حل ڪيو ويو. ورهاڱي جا زخم ۽ لڏپلاڻ جا اثر ڏهاڪن تائين محسوس ڪيا ويا."}], "sections_ur": [{"heading": "تعارف", "text": "1947 میں برطانوی ہندوستان کی تقسیم سے ہندوستان اور پاکستان دو آزاد ریاستیں بنے۔ 3 جون 1947 کے منصوبے اور 18 جولائی کے انڈین انڈیپینڈنس ایکٹ کے تحت اقتدار منتقل ہوا۔ پاکستان 14 اگست 1947 کو وجود میں آیا، جبکہ ہندوستان 15 اگست کو آزاد ہوا۔"}, {"heading": "ریڈکلف لائن", "text": "پنجاب اور بنگال کی حد بندی کے لیے سر سائرل ریڈکلف کی صدارت میں باؤنڈری کمیشن قائم کیے گئے۔ ریڈکلف، جو پہلے کبھی ہندوستان نہ آیا تھا، نے صرف پانچ ہفتوں میں حدیں بنائیں، جن کا اعلان 17 اگست 1947 کو ہوا۔ اس لائن نے مسلم اکثریتی علاقے پاکستان اور ہندو اکثریتی علاقے ہندوستان کو دیے۔"}, {"heading": "ہجرت اور تشدد", "text": "تقسیم سے تاریخ کی سب سے بڑی ہجرت ہوئی: اندازاً ایک سے ڈیڑھ کروڑ لوگ سرحدیں پار کر گئے۔ 1951 کی مردم شماری کے مطابق 72 لاکھ سے زیادہ مسلمان ہندوستان سے پاکستان آئے اور اتنے ہی ہندو اور سکھ پاکستان سے ہندوستان گئے۔ فرقہ وارانہ تشدد میں مرنے والوں کی تعداد علما میں اختلافی ہے؛ اندازے پانچ لاکھ سے بیس لاکھ تک ہیں۔"}, {"heading": "نتائج", "text": "تقسیم سے کشمیر کا مسئلہ پیدا ہوا، جس پر 1947-48 میں پہلی پاک۔بھارت جنگ ہوئی۔ پنجاب کا آبپاشی نظام بٹ گیا، جسے بعد میں 1960 کے سندھ طاس معاہدے سے حل کیا گیا۔ تقسیم کے زخم اور ہجرت کے اثرات دہائیوں تک محسوس کیے گئے۔"}], "sources": [{"title": "The 1947 Partition: Drawing the Indo-Pakistani Boundary — American Diplomacy (UNC)", "url": "https://americandiplomacy.web.unc.edu/2002/02/the-1947-partition-drawing-the-indo-pakistani-boundary/"}, {"title": "The Radcliffe Line — Testbook", "url": "https://testbook.com/question-answer/the-radcliffe-line-is-the-boundary-demarcation-lin--681e291e5370df2fd730abed"}], "summary_sd": "1947 جي ورهاڱي سان هندستان ۽ پاڪستان وجود ۾ آيا. ريڊڪلف لائين پنجن هفتن ۾ ٺاهي وئي. ان سان هڪ کان ڏيڍ ڪروڙ ماڻهن جي لڏپلاڻ ۽ وڏي پيماني تي تشدد ٿيو. ورهاڱي سان ڪشمير جو مسئلو ۽ ڏهاڪن تائين هلندڙ ڇڪتاڻ پيدا ٿي.", "summary_ur": "1947 کی تقسیم سے ہندوستان اور پاکستان وجود میں آئے۔ ریڈکلف لائن پانچ ہفتوں میں بنائی گئی۔ اس سے ایک سے ڈیڑھ کروڑ لوگوں کی ہجرت اور بڑے پیمانے پر تشدد ہوا۔ تقسیم سے کشمیر کا مسئلہ اور دہائیوں تک چلنے والی کشیدگی پیدا ہوئی۔", "timeline": [{"era": "3 جون 1947", "text_sd": "ورهاڱي جي منصوبي جو اعلان.", "text_ur": "تقسیم کے منصوبے کا اعلان۔"}, {"era": "14 اگست 1947", "text_sd": "پاڪستان جو قيام.", "text_ur": "پاکستان کا قیام۔"}, {"era": "17 اگست 1947", "text_sd": "ريڊڪلف لائين جو اعلان.", "text_ur": "ریڈکلف لائن کا اعلان۔"}, {"era": "1947-1948", "text_sd": "ڪشمير تي پهرين پاڪ-هند جنگ.", "text_ur": "کشمیر پر پہلی پاک۔بھارت جنگ۔"}]};
HIST_DATA["special-migration-historical-events"] = {"country": "Pakistan", "id": "migration-historical-events", "kind": "topic", "name_sd": "لڏپلاڻ ۽ تاريخي واقعا", "name_ur": "ہجرت اور تاریخی واقعات", "region": "Pakistan", "sections_sd": [{"heading": "تعارف", "text": "پاڪستان جي تاريخ ۾ لڏپلاڻ جا ڪيترائي وڏا مرحلا آيا آهن، جن ملڪ جي آبادي، ثقافت ۽ سياست تي گهرا اثر ڇڏيا. انهن ۾ 1947 جي ورهاڱي واري لڏپلاڻ، اوڀر پاڪستان جي بحران ۽ 1979 کان پوءِ افغان مهاجرن جي آمد سڀ کان اهم آهن."}, {"heading": "1947 جي لڏپلاڻ", "text": "ورهاڱي تي اندازاً هڪ کان ڏيڍ ڪروڙ ماڻهو سرحدون پار ڪيا. 1951 جي آدمشماري موجب 72 لک کان وڌيڪ مسلمان هندستان کان پاڪستان آيا، جن مان وڏي تعداد ڪراچي ۽ پنجاب ۾ آباد ٿي. انهن مهاجرن کي مہاجر سڏيو وڃي ٿو، ۽ هنن ڪراچي جي شهري ثقافت ٺاهڻ ۾ اهم ڪردار ادا ڪيو."}, {"heading": "1971 جو بحران", "text": "1970 جي چونڊن کان پوءِ سياسي ڇڪتاڻ اوڀر پاڪستان ۾ گهرو ويڙهه ۾ تبديل ٿي. هندستان جي مداخلت سان ڊسمبر 1971 ۾ اوڀر پاڪستان بنگله ديش بڻجي ويو. هن واقعي سان لکن ماڻهن جي لڏپلاڻ ٿي ۽ پاڪستان جي تاريخ جو سڀ کان وڏو سياسي ڌچڪو لڳو."}, {"heading": "افغان مهاجر", "text": "1979 ۾ سوويت يونين جي افغانستان تي حملي کان پوءِ لکن افغان پاڪستان آيا. 1979 جي آخر تائين 4 لک افغان پاڪستان ۾ هئا، ۽ 1990 تائين رجسٽرڊ مهاجرن جو انگ 32 لکن تائين پهچي ويو. گڏيل قومن جي مهاجرن واري اداري (UNHCR) جي مدد سان پاڪستان ڏهاڪن تائين دنيا جي سڀ کان وڏي مهاجر آباديءَ جي ميزباني ڪئي."}], "sections_ur": [{"heading": "تعارف", "text": "پاکستان کی تاریخ میں ہجرت کے کئی بڑے مراحل آئے ہیں، جنہوں نے ملک کی آبادی، ثقافت اور سیاست پر گہرے اثرات چھوڑے۔ ان میں 1947 کی تقسیم والی ہجرت، مشرقی پاکستان کا بحران اور 1979 کے بعد افغان مہاجرین کی آمد سب سے اہم ہیں۔"}, {"heading": "1947 کی ہجرت", "text": "تقسیم پر اندازاً ایک سے ڈیڑھ کروڑ لوگ سرحدیں پار کر گئے۔ 1951 کی مردم شماری کے مطابق 72 لاکھ سے زیادہ مسلمان ہندوستان سے پاکستان آئے، جن میں سے بڑی تعداد کراچی اور پنجاب میں آباد ہوئی۔ ان مہاجرین کو مہاجر کہا جاتا ہے، اور انہوں نے کراچی کی شہری ثقافت بنانے میں اہم کردار ادا کیا۔"}, {"heading": "1971 کا بحران", "text": "1970 کے انتخابات کے بعد سیاسی کشیدگی مشرقی پاکستان میں خانہ جنگی میں بدل گئی۔ ہندوستان کی مداخلت سے دسمبر 1971 میں مشرقی پاکستان بنگلہ دیش بن گیا۔ اس واقعے سے لاکھوں لوگوں کی ہجرت ہوئی اور پاکستان کی تاریخ کا سب سے بڑا سیاسی دھچکا لگا۔"}, {"heading": "افغان مہاجرین", "text": "1979 میں سوویت یونین کے افغانستان پر حملے کے بعد لاکھوں افغان پاکستان آئے۔ 1979 کے آخر تک 4 لاکھ افغان پاکستان میں تھے، اور 1990 تک رجسٹرڈ مہاجرین کی تعداد 32 لاکھ تک پہنچ گئی۔ اقوام متحدہ کے مہاجرین کے ادارے (UNHCR) کی مدد سے پاکستان دہائیوں تک دنیا کی سب سے بڑی مہاجر آبادی کی میزبانی کرتا رہا۔"}], "sources": [{"title": "Pakistan's Afghan refugees: A timeline — CRSS", "url": "https://crss.pk/pakistans-afghan-refugees-a-timeline/"}, {"title": "Afghanistan: the unending crisis — UNHCR Refugees Magazine", "url": "https://www.unhcr.org/publications/refugees-magazine-issue-108-afghanistan-unending-crisis-biggest-caseload-world"}, {"title": "Timeline of Afghan displacements into Pakistan — ReliefWeb (IRIN)", "url": "https://reliefweb.int/report/pakistan/timeline-afghan-displacements-pakistan"}], "summary_sd": "پاڪستان جي تاريخ ۾ ٽي وڏيون لڏپلاڻون ٿيون: 1947 ۾ ورهاڱي تي ڪروڙين ماڻهن جي لڏپلاڻ، 1971 ۾ اوڀر پاڪستان جو بحران، ۽ 1979 کان پوءِ لکن افغان مهاجرن جي آمد. انهن واقعن ملڪ جي آبادي ۽ سياست کي بنيادي طور تي بدلائي ڇڏيو.", "summary_ur": "پاکستان کی تاریخ میں تین بڑی ہجرتیں ہوئیں: 1947 میں تقسیم پر کروڑوں لوگوں کی ہجرت، 1971 میں مشرقی پاکستان کا بحران، اور 1979 کے بعد لاکھوں افغان مہاجرین کی آمد۔ ان واقعات نے ملک کی آبادی اور سیاست کو بنیادی طور پر بدل دیا۔", "timeline": [{"era": "1947ء", "text_sd": "ورهاڱي تي تاريخ جي سڀ کان وڏي لڏپلاڻ.", "text_ur": "تقسیم پر تاریخ کی سب سے بڑی ہجرت۔"}, {"era": "1971ء", "text_sd": "اوڀر پاڪستان الڳ ٿي بنگله ديش بڻيو.", "text_ur": "مشرقی پاکستان الگ ہو کر بنگلہ دیش بنا۔"}, {"era": "1979ء", "text_sd": "افغان مهاجرن جي آمد شروع؛ سال جي آخر تائين 4 لک مهاجر.", "text_ur": "افغان مہاجرین کی آمد شروع؛ سال کے آخر تک 4 لاکھ مہاجرین۔"}, {"era": "1990ء", "text_sd": "رجسٽرڊ افغان مهاجرن جو انگ 32 لکن تائين پهتو.", "text_ur": "رجسٹرڈ افغان مہاجرین کی تعداد 32 لاکھ تک پہنچی۔"}]};
HIST_DATA["special-post-1947-pakistan"] = {"country": "Pakistan", "id": "post-1947-pakistan", "kind": "topic", "name_sd": "1947 کان پوءِ پاڪستان", "name_ur": "1947 کے بعد پاکستان", "region": "Pakistan", "sections_sd": [{"heading": "ابتدائي سال (1947-1958)", "text": "14 آگسٽ 1947 تي پاڪستان وجود ۾ آيو؛ قائداعظم محمد علي جناح پهريان گورنر جنرل ۽ لياقت علي خان پهريان وزيراعظم بڻيا. قائداعظم 11 سيپٽمبر 1948 تي وفات ڪري ويا ۽ لياقت علي خان 16 آڪٽوبر 1951 تي راولپنڊي ۾ قتل ڪيا ويا. 1956 ۾ پهريون آئين نافذ ٿيو ۽ پاڪستان اسلامي جمهوريه بڻيو."}, {"heading": "فوجي حڪومتون ۽ جنگيون", "text": "1958 ۾ جنرل ايوب خان مارشل لا لڳائي اقتدار سنڀاليو. 1965 ۾ ڪشمير تي هندستان سان ٻئي جنگ ٿي. 1969 ۾ يحيٰ خان اقتدار سنڀاليو. 1970 جي چونڊن کان پوءِ پيدا ٿيل بحران ۾ 1971 ۾ اوڀر پاڪستان الڳ ٿي بنگله ديش بڻجي ويو."}, {"heading": "1970 ۽ 1980 وارو ڏهاڪو", "text": "1971 کان پوءِ ذوالفقار علي ڀٽو اقتدار سنڀاليو ۽ 1973 جو آئين نافذ ٿيو، جيڪو اڄ به ملڪ جو آئين آهي. 1977 ۾ جنرل ضياءُ الحق مارشل لا لڳايو؛ ڀٽو کي 1979 ۾ ڦاسي ڏني وئي. ضياءُ الحق جو دور سوويت-افغان جنگ سان ڳنڍيل رهيو، ۽ 1988 ۾ هوائي حادثي ۾ سندس وفات ٿي."}, {"heading": "جمهوري دور ۽ اڳتي", "text": "1988 کان 1999 تائين بينظير ڀٽو ۽ نواز شريف جون حڪومتون متبادل رهيون. 1998 ۾ چاغي ۾ ايٽمي ڌماڪا ڪري پاڪستان اعلانيل ايٽمي طاقت بڻيو. 1999 ۾ جنرل پرويز مشرف اقتدار سنڀاليو، 2008 ۾ جمهوري نظام بحال ٿيو. 2018 ۾ عمران خان وزيراعظم بڻيا، جن کي 2022 ۾ عدم اعتماد ذريعي هٽايو ويو."}], "sections_ur": [{"heading": "ابتدائی سال (1947-1958)", "text": "14 اگست 1947 کو پاکستان وجود میں آیا؛ قائداعظم محمد علی جناح پہلے گورنر جنرل اور لیاقت علی خان پہلے وزیراعظم بنے۔ قائداعظم 11 ستمبر 1948 کو وفات کر گئے اور لیاقت علی خان 16 اکتوبر 1951 کو راولپنڈی میں قتل کیے گئے۔ 1956 میں پہلا آئین نافذ ہوا اور پاکستان اسلامی جمہوریہ بنا۔"}, {"heading": "فوجی حکومتیں اور جنگیں", "text": "1958 میں جنرل ایوب خان نے مارشل لا لگا کر اقتدار سنبھالا۔ 1965 میں کشمیر پر ہندوستان سے دوسری جنگ ہوئی۔ 1969 میں یحییٰ خان نے اقتدار سنبھالا۔ 1970 کے انتخابات کے بعد پیدا شدہ بحران میں 1971 میں مشرقی پاکستان الگ ہو کر بنگلہ دیش بن گیا۔"}, {"heading": "1970 اور 1980 کی دہائی", "text": "1971 کے بعد ذوالفقار علی بھٹو نے اقتدار سنبھالا اور 1973 کا آئین نافذ ہوا، جو آج بھی ملک کا آئین ہے۔ 1977 میں جنرل ضیاء الحق نے مارشل لا لگایا؛ بھٹو کو 1979 میں پھانسی دی گئی۔ ضیاء الحق کا دور سوویت۔افغان جنگ سے جڑا رہا، اور 1988 میں ہوائی حادثے میں ان کی وفات ہوئی۔"}, {"heading": "جمہوری دور اور آگے", "text": "1988 سے 1999 تک بینظیر بھٹو اور نواز شریف کی حکومتیں متبادل رہیں۔ 1998 میں چاغی میں ایٹمی دھماکے کر کے پاکستان اعلانیہ ایٹمی طاقت بنا۔ 1999 میں جنرل پرویز مشرف نے اقتدار سنبھالا، 2008 میں جمہوری نظام بحال ہوا۔ 2018 میں عمران خان وزیراعظم بنے، جنہیں 2022 میں عدم اعتماد سے ہٹایا گیا۔"}], "sources": [{"title": "Timeline: Pakistan from 1947 — Trinicenter", "url": "http://www.trinicenter.com/historicalviews/pakistantimeline.htm"}, {"title": "Pakistan History (1947-2025) — Scribd timeline", "url": "https://www.scribd.com/document/855713791/Pakistan-History-1947-to-2025-PPSC"}], "summary_sd": "1947 کان پوءِ پاڪستان ڪيترن ئي مرحلن مان گذريو: ابتدائي اڳواڻن جي وفات، 1956 جو پهريون آئين، فوجي حڪومتون، 1965 ۽ 1971 جون جنگيون، بنگله ديش جو قيام، 1973 جو آئين، ۽ 1988 کان پوءِ جمهوري ۽ فوجي دورن جو متبادل. 1998 ۾ پاڪستان ايٽمي طاقت بڻيو.", "summary_ur": "1947 کے بعد پاکستان کئی مراحل سے گزرا: ابتدائی رہنماؤں کی وفات، 1956 کا پہلا آئین، فوجی حکومتیں، 1965 اور 1971 کی جنگیں، بنگلہ دیش کا قیام، 1973 کا آئین، اور 1988 کے بعد جمہوری و فوجی ادوار کا متبادل۔ 1998 میں پاکستان ایٹمی طاقت بنا۔", "timeline": [{"era": "1947-1948", "text_sd": "پاڪستان جو قيام؛ قائداعظم جي وفات (11 سيپٽمبر 1948).", "text_ur": "پاکستان کا قیام؛ قائداعظم کی وفات (11 ستمبر 1948)۔"}, {"era": "1956ء", "text_sd": "پهريون آئين؛ پاڪستان اسلامي جمهوريه بڻيو.", "text_ur": "پہلا آئین؛ پاکستان اسلامی جمہوریہ بنا۔"}, {"era": "1965ء", "text_sd": "هندستان سان ٻئي جنگ.", "text_ur": "ہندوستان سے دوسری جنگ۔"}, {"era": "1971ء", "text_sd": "اوڀر پاڪستان الڳ ٿي بنگله ديش بڻيو.", "text_ur": "مشرقی پاکستان الگ ہو کر بنگلہ دیش بنا۔"}, {"era": "1973ء", "text_sd": "نئون آئين نافذ ٿيو (اڄ به نافذ).", "text_ur": "نیا آئین نافذ ہوا (آج بھی نافذ)۔"}, {"era": "1998ء", "text_sd": "چاغي ۾ ايٽمي ڌماڪا؛ پاڪستان ايٽمي طاقت بڻيو.", "text_ur": "چاغی میں ایٹمی دھماکے؛ پاکستان ایٹمی طاقت بنا۔"}]};
HIST_DATA["special-archaeological-sites"] = {"country": "Pakistan", "id": "archaeological-sites", "kind": "topic", "name_sd": "قديم آثار", "name_ur": "آثار قدیمہ", "region": "Pakistan", "sections_sd": [{"heading": "تعارف", "text": "پاڪستان ۾ قديم آثارن جو وڏو خزانو آهي، جيڪو پٿر جي دور کان وٺي اسلامي دور تائين هزارين سالن جي تاريخ کي ڍڪي ٿو. انهن ۾ يونيسڪو عالمي ورثي جا ڇهه ماڳ به شامل آهن. هيٺ سڀ کان اهم ماڳن جو اختصار ڏنو ويو آهي."}, {"heading": "مهرڳڙهه (بلوچستان)", "text": "لڳ ڀڳ 7000 ق.م جو قديم زرعي ڳوٺ، جيڪو ڏکڻ ايشيا ۾ پوک ۽ پالنا جي قديم ترين ثبوتن مان هڪ آهي. 1974 ۾ فرانسيسي ماهرن دريافت ڪيو. ان کي سنڌو ماٿريءَ جي ٿهذيب جو اڳوڻو سمجهيو وڃي ٿو."}, {"heading": "موھن جو دڙو (سنڌ)", "text": "سنڌو ماٿريءَ جي ٿهذيب جو سڀ کان وڏو شهر (2600-1900 ق.م). 1922 ۾ دريافت ٿيو ۽ 1980 ۾ ڏکڻ ايشيا جو پهريون يونيسڪو عالمي ورثو بڻيو. وڏو غسل خانو ۽ گٽر نظام ان جي شهري منصوبابنديءَ جا شاهڪار آهن."}, {"heading": "ھڙپہ (پنجاب)", "text": "ٿهذيب جو ٻيو وڏو شهر، جنهن جي نالي تي پوري ٿهذيب کي ھڙپہ ٿهذيب چيو وڃي ٿو. 1920 واري ڏهاڪي ۾ کوٽائي ٿي. يونيسڪو ان کي موھن جو دڙو جي واڌ طور نامزد ڪرڻ جي تجويز ڏني آهي."}, {"heading": "ٽيڪسلا (پنجاب)", "text": "گنڌارا ٿهذيب جو اهم مرڪز ۽ قديم سِکيا جو گهر. ڇهين صدي ق.م کان پوءِ جا آثار؛ ٻڌ اسٽوپا، خانقاهون ۽ ٽيڪسلا عجائب گھر (1918) هتي آهن. 1980 ۾ يونيسڪو عالمي ورثو قرار ڏنو ويو."}, {"heading": "تخت ڀائي (خيبر پختونخوا)", "text": "پهرين صدي عيسوي ۾ قائم ٿيل ٻڌ خانقاهه، جيڪا گنڌارا علائقي ۾ ٻڌ مت جي سڀ کان شاندار يادگارن مان هڪ آهي. ويجهو شهر باقيات سان گڏ 1980 ۾ يونيسڪو عالمي ورثو بڻيو."}, {"heading": "ڀنڀور (سنڌ)", "text": "قديم بندرگاهه وارو شهر، جنهن کي ڪيترائي عالم ۽ آثار قديمه جا ماهر ديبَل سان سڃاڻن ٿا، جيتوڻيڪ ان سڃاڻپ تي بحث جاري آهي. هتي 727 عيسوي جي ڪتبي واري مسجد جا کنڊر آهن، جيڪا علائقي جي قديم ترين مسجدن مان هڪ آهي. يونيسڪو جي عارضي فهرست ۾ شامل آهي."}, {"heading": "مڪلي (سنڌ، ٺٽو)", "text": "دنيا جي وڏي ۾ وڏي مسلمان قبرستانن مان هڪ، جيڪا 10 ڪلوميٽرن تي پکڙيل آهي. بادشاهن، بزرگن ۽ عالمن جا مقبرا هتي آهن. 1981 ۾ يونيسڪو عالمي ورثو قرار ڏنو ويو."}, {"heading": "رني ڪوٽ (سنڌ)", "text": "سنڌ جي عظيم ديوار سڏيو وڃي ٿو. ان جي باني بابت عالمن ۾ اختلاف آهي؛ ڪيترائي ذريعا ان جي تعمير ٽالپر دور (لڳ ڀڳ 1812) سان ڳنڍين ٿا. 1993 کان يونيسڪو جي عارضي فهرست ۾ آهي."}], "sections_ur": [{"heading": "تعارف", "text": "پاکستان میں آثار قدیمہ کا بڑا خزانہ ہے، جو پتھر کے دور سے لے کر اسلامی دور تک ہزاروں سال کی تاریخ کو ڈھکتا ہے۔ ان میں یونیسکو عالمی ورثے کے چھ مقامات بھی شامل ہیں۔ ذیل میں سب سے اہم مقامات کا خلاصہ دیا گیا ہے۔"}, {"heading": "مہر گڑھ (بلوچستان)", "text": "تقریباً 7000 قبل مسیح کا قدیم زرعی گاؤں، جو جنوبی ایشیا میں کاشت اور پالن کے قدیم ترین ثبوتوں میں سے ایک ہے۔ 1974 میں فرانسیسی ماہرین نے دریافت کیا۔ اسے وادی سندھ کی تہذیب کا پیشرو سمجھا جاتا ہے۔"}, {"heading": "موہنجوداڑو (سندھ)", "text": "وادی سندھ کی تہذیب کا سب سے بڑا شہر (2600-1900 قبل مسیح)۔ 1922 میں دریافت ہوا اور 1980 میں جنوبی ایشیا کا پہلا یونیسکو عالمی ورثہ بنا۔ بڑا غسل خانہ اور نکاسی کا نظام اس کی شہری منصوبہ بندی کے شاہکار ہیں۔"}, {"heading": "ہڑپہ (پنجاب)", "text": "تہذیب کا دوسرا بڑا شہر، جس کے نام پر پوری تہذیب کو ہڑپہ تہذیب کہا جاتا ہے۔ 1920 کی دہائی میں کھدائی ہوئی۔ یونیسکو اسے موہنجوداڑو کی توسیع کے طور پر نامزد کرنے کی تجویز دی گئی ہے۔"}, {"heading": "ٹیکسلا (پنجاب)", "text": "گندھارا تہذیب کا اہم مرکز اور قدیم تعلیم کا گھر۔ چھٹی صدی قبل مسیح کے بعد کے آثار؛ بدھ اسٹوپا، خانقاہیں اور ٹیکسلا عجائب گھر (1918) یہاں ہیں۔ 1980 میں یونیسکو عالمی ورثہ قرار دیا گیا۔"}, {"heading": "تخت بھائی (خیبر پختونخوا)", "text": "پہلی صدی عیسوی میں قائم شدہ بدھ خانقاہ، جو گندھارا علاقے میں بدھ مت کی سب سے شاندار یادگاروں میں سے ایک ہے۔ قریبی شہر کی باقیات کے ساتھ 1980 میں یونیسکو عالمی ورثہ بنا۔"}, {"heading": "بھنبھور (سندھ)", "text": "قدیم بندرگاہ والا شہر، جسے کئی علما اور ماہرین آثار قدیمہ دیبل سے پہچانتے ہیں، اگرچہ اس شناخت پر بحث جاری ہے۔ یہاں 727 عیسوی کے کتبے والی مسجد کے کھنڈر ہیں، جو علاقے کی قدیم ترین مسجدوں میں سے ایک ہے۔ یونیسکو کی عارضی فہرست میں شامل ہے۔"}, {"heading": "مکلی (سندھ، ٹھٹھہ)", "text": "دنیا کے بڑے مسلمان قبرستانوں میں سے ایک، جو 10 کلومیٹر پر پھیلا ہے۔ بادشاہوں، بزرگوں اور علما کے مقبرے یہاں ہیں۔ 1981 میں یونیسکو عالمی ورثہ قرار دیا گیا۔"}, {"heading": "رنی کوٹ (سندھ)", "text": "سندھ کی عظیم دیوار کہلاتا ہے۔ اس کے بانی کے بارے میں علما میں اختلاف ہے؛ کئی ذرائع اس کی تعمیر ٹالپر دور (تقریباً 1812) سے جوڑتے ہیں۔ 1993 سے یونیسکو کی عارضی فہرست میں ہے۔"}], "sources": [{"title": "Pakistan's six World Heritage properties — PWHI 48COM Session Brief (PDF)", "url": "https://pwhi.digital/assets/PWHI-48COM-Session-Brief.pdf"}, {"title": "List of World Heritage Sites in Pakistan — Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_World_Heritage_Sites_in_Pakistan"}, {"title": "Banbhore — Wikipedia", "url": "https://en.wikipedia.org/wiki/Banbhore"}, {"title": "List of archaeological sites in Pakistan — Wikipedia", "url": "https://en.wikipedia.org/wiki/List_of_archaeological_sites_in_Pakistan"}], "summary_sd": "پاڪستان ۾ هزارين سال پراڻا قديم آثار آهن: مهرڳڙهه، موھن جو دڙو، ھڙپہ، ٽيڪسلا، تخت ڀائي، ڀنڀور، مڪلي ۽ رني ڪوٽ. انهن مان ڇهه يونيسڪو عالمي ورثو آهن. هي ماڳ پٿر جي دور کان اسلامي دور تائين هن ڌرتيءَ جي تاريخ ٻڌائين ٿا.", "summary_ur": "پاکستان میں ہزاروں سال پرانے آثار قدیمہ ہیں: مہر گڑھ، موہنجوداڑو، ہڑپہ، ٹیکسلا، تخت بھائی، بھنبھور، مکلی اور رنی کوٹ۔ ان میں سے چھ یونیسکو عالمی ورثہ ہیں۔ یہ مقامات پتھر کے دور سے اسلامی دور تک اس سرزمین کی تاریخ بتاتے ہیں۔", "timeline": [{"era": "7000 قبل مسیح", "text_sd": "مهرڳڙهه آباد ٿيو.", "text_ur": "مہر گڑھ آباد ہوا۔"}, {"era": "2600 قبل مسیح", "text_sd": "موھن جو دڙو ۽ ھڙپہ عروج تي.", "text_ur": "موہنجوداڑو اور ہڑپہ عروج پر۔"}, {"era": "پہلی صدی عیسوی", "text_sd": "تخت ڀائي جي خانقاهه قائم ٿي.", "text_ur": "تخت بھائی کی خانقاہ قائم ہوئی۔"}, {"era": "1980-1981ء", "text_sd": "ڇهه ماڳ يونيسڪو عالمي ورثو قرار (موھن جو دڙو، ٽيڪسلا، تخت ڀائي 1980؛ مڪلي 1981).", "text_ur": "چھ مقامات یونیسکو عالمی ورثہ قرار (موہنجوداڑو، ٹیکسلا، تخت بھائی 1980؛ مکلی 1981)۔"}]};
HIST_DATA["special-historical-personalities"] = {"country": "Pakistan", "id": "historical-personalities", "kind": "topic", "name_sd": "تاريخي شخصيتون", "name_ur": "تاریخی شخصیات", "region": "Pakistan", "sections_sd": [{"heading": "تعارف", "text": "پاڪستان جي تاريخ ٺاهڻ ۾ ڪيترين ئي شخصيتن اهم ڪردار ادا ڪيو، عالمن ۽ مصلحن کان وٺي سياسي اڳواڻن تائين. هيٺ انهن مان سڀ کان اهم شخصيتن جو مختصر تعارف ڏنو ويو آهي."}, {"heading": "شاهه ولي الله (1703-1762)", "text": "دهلي جا عظيم عالم ۽ مصلح. هن قرآن جو فارسيءَ ۾ ترجمو ڪيو ۽ حجۃ الله البالغه جهڙيون ڪتابون لکيون. سندس پٽن قرآن جو اردو ۾ ترجمو ڪيو. کيس برصغير ۾ اسلامي فڪر جي تجديد جو باني سمجهيو وڃي ٿو."}, {"heading": "سر سيد احمد خان (1817-1898)", "text": "مسلمانن جي تعليمي ۽ سماجي مصلح. 1857 کان پوءِ هن مسلمانن کي جديد تعليم ڏانهن راغب ڪيو، 1875 ۾ علي ڳڙهه ۾ ايم. اي. او. ڪاليج قائم ڪيو، جيڪو بعد ۾ علي ڳڙهه مسلم يونيورسٽي بڻيو. سندس تحريک کي علي ڳڙهه تحريک چيو وڃي ٿو."}, {"heading": "قائداعظم محمد علي جناح (1876-1948)", "text": "پاڪستان جا باني. 25 ڊسمبر 1876 تي ڪراچي ۾ ڄاوا، لنڪن ان مان بئريسٽر بڻيا. 1913 ۾ مسلم ليگ ۾ شامل ٿيا ۽ تحريک پاڪستان جي قيادت ڪئي. 14 آگسٽ 1947 تي پاڪستان جا پهريان گورنر جنرل بڻيا؛ 11 سيپٽمبر 1948 تي وفات ڪيائون."}, {"heading": "علامه محمد اقبال (1877-1938)", "text": "شاعر، فلسفي ۽ تحريک پاڪستان جا فڪري رهنما. 9 نومبر 1877 تي سيالڪوٽ ۾ ڄاوا. 1930 جي الاه آباد خطبي ۾ اتر-اولهه هندستان ۾ مسلم رياست جو تصور پيش ڪيائون. سندس شاعري (بانگ درا، بال جبريل) اردو ۽ فارسي ادب جو سرمايو آهي. 21 اپريل 1938 تي لاهور ۾ وفات ڪيائون."}, {"heading": "لياقت علي خان (1895-1951)", "text": "پاڪستان جا پهريان وزيراعظم (1947-1951) ۽ قائداعظم جا ويجها ساٿي. قرارداد مقاصد جا خالق. 16 آڪٽوبر 1951 تي راولپنڊي ۾ هڪ جلسي دوران قتل ڪيا ويا."}, {"heading": "فاطمه جناح (1893-1967)", "text": "مادر ملت، قائداعظم جي ننڍي ڀيڻ. تحريک پاڪستان ۾ سرگرم ڪردار ادا ڪيائون ۽ عورتن جي حقن لاءِ ڪم ڪيائون. 1965 جي صدارتي چونڊ ۾ ايوب خان خلاف اميدوار هيون. 9 جولاءِ 1967 تي وفات ڪيائون."}, {"heading": "مولانا محمد علي جوهر (1878-1931)", "text": "خلافت تحريڪ جا اڳواڻ ۽ صحافي. انگريزن خلاف جدوجهد ۾ نمايان ڪردار؛ 1931 ۾ لنڊن ۾ گول ميز ڪانفرنس دوران وفات ڪيائون ۽ يروشلم ۾ دفن ٿيا."}, {"heading": "چوڌري رحمت علي (1897-1951)", "text": "1933 ۾ پنهنجي مشهور پمفليٽ ناؤ اور نيور ۾ پاڪستان جو نالو تجويز ڪندڙ. ڪيمبرج ۾ پڙهائي دوران پاڪستان نيشنل موومينٽ هلائي. 1951 ۾ وفات ڪيائون."}], "sections_ur": [{"heading": "تعارف", "text": "پاکستان کی تاریخ بنانے میں کئی شخصیتوں نے اہم کردار ادا کیا، علما اور مصلحین سے لے کر سیاسی رہنماؤں تک۔ ذیل میں ان میں سے سب سے اہم شخصیتوں کا مختصر تعارف دیا گیا ہے۔"}, {"heading": "شاہ ولی اللہ (1703-1762)", "text": "دہلی کے عظیم عالم اور مصلح۔ انہوں نے قرآن کا فارسی میں ترجمہ کیا اور حجۃ اللہ البالغہ جیسی کتابیں لکھیں۔ ان کے بیٹوں نے قرآن کا اردو میں ترجمہ کیا۔ انہیں برصغیر میں اسلامی فکر کی تجدید کا بانی سمجھا جاتا ہے۔"}, {"heading": "سر سید احمد خان (1817-1898)", "text": "مسلمانوں کے تعلیمی و سماجی مصلح۔ 1857 کے بعد انہوں نے مسلمانوں کو جدید تعلیم کی طرف راغب کیا، 1875 میں علی گڑھ میں ایم۔اے۔او۔ کالج قائم کیا، جو بعد میں علی گڑھ مسلم یونیورسٹی بنا۔ ان کی تحریک کو علی گڑھ تحریک کہا جاتا ہے۔"}, {"heading": "قائداعظم محمد علی جناح (1876-1948)", "text": "پاکستان کے بانی۔ 25 دسمبر 1876 کو کراچی میں پیدا ہوئے، لنکن ان سے بیرسٹر بنے۔ 1913 میں مسلم لیگ میں شامل ہوئے اور تحریک پاکستان کی قیادت کی۔ 14 اگست 1947 کو پاکستان کے پہلے گورنر جنرل بنے؛ 11 ستمبر 1948 کو وفات پائی۔"}, {"heading": "علامہ محمد اقبال (1877-1938)", "text": "شاعر، فلسفی اور تحریک پاکستان کے فکری رہنما۔ 9 نومبر 1877 کو سیالکوٹ میں پیدا ہوئے۔ 1930 کے الہ آباد خطبے میں شمال۔مغربی ہندوستان میں مسلم ریاست کا تصور پیش کیا۔ ان کی شاعری (بانگ درا، بال جبریل) اردو و فارسی ادب کا سرمایہ ہے۔ 21 اپریل 1938 کو لاہور میں وفات پائی۔"}, {"heading": "لیاقت علی خان (1895-1951)", "text": "پاکستان کے پہلے وزیراعظم (1947-1951) اور قائداعظم کے قریبی ساتھی۔ قرارداد مقاصد کے خالق۔ 16 اکتوبر 1951 کو راولپنڈی میں ایک جلسے کے دوران قتل کیے گئے۔"}, {"heading": "فاطمہ جناح (1893-1967)", "text": "مادر ملت، قائداعظم کی چھوٹی بہن۔ تحریک پاکستان میں سرگرم کردار ادا کیا اور عورتوں کے حقوق کے لیے کام کیا۔ 1965 کے صدارتی انتخاب میں ایوب خان کے خلاف امیدوار تھیں۔ 9 جولائی 1967 کو وفات پائی۔"}, {"heading": "مولانا محمد علی جوہر (1878-1931)", "text": "خلافت تحریک کے رہنما اور صحافی۔ انگریزوں کے خلاف جدوجہد میں نمایاں کردار؛ 1931 میں لندن میں گول میز کانفرنس کے دوران وفات پائی اور یروشلم میں دفن ہوئے۔"}, {"heading": "چوہدری رحمت علی (1897-1951)", "text": "1933 میں اپنے مشہور پمفلٹ ناؤ اور نیور میں پاکستان کا نام تجویز کرنے والے۔ کیمبرج میں پڑھائی کے دوران پاکستان نیشنل موومنٹ چلائی۔ 1951 میں وفات پائی۔"}], "sources": [{"title": "Founders of Pakistan and Their Legacy — Scribd", "url": "https://www.scribd.com/document/669012866/Founders-of-Pakistan"}, {"title": "Muhammad ibn al-Qasim — Wikipedia", "url": "https://en.wikipedia.org/wiki/Muhammad_ibn_Qasim"}], "summary_sd": "پاڪستان جي تاريخ جون اهم شخصيتون: شاهه ولي الله (مصلح)، سر سيد احمد خان (تعليمي رهنما)، قائداعظم محمد علي جناح (باني پاڪستان)، علامه اقبال (فڪري رهنما)، لياقت علي خان (پهريان وزيراعظم)، فاطمه جناح (مادر ملت)، مولانا محمد علي جوهر ۽ چوڌري رحمت علي.", "summary_ur": "پاکستان کی تاریخ کی اہم شخصیات: شاہ ولی اللہ (مصلح)، سر سید احمد خان (تعلیمی رہنما)، قائداعظم محمد علی جناح (بانی پاکستان)، علامہ اقبال (فکری رہنما)، لیاقت علی خان (پہلے وزیراعظم)، فاطمہ جناح (مادر ملت)، مولانا محمد علی جوہر اور چوہدری رحمت علی۔", "timeline": [{"era": "1703ء", "text_sd": "شاهه ولي الله جي پيدائش.", "text_ur": "شاہ ولی اللہ کی پیدائش۔"}, {"era": "1817ء", "text_sd": "سر سيد احمد خان جي پيدائش.", "text_ur": "سر سید احمد خان کی پیدائش۔"}, {"era": "1876-1877ء", "text_sd": "قائداعظم (1876) ۽ علامه اقبال (1877) جي پيدائش.", "text_ur": "قائداعظم (1876) اور علامہ اقبال (1877) کی پیدائش۔"}, {"era": "1930ء", "text_sd": "اقبال جو الاه آباد خطبو.", "text_ur": "اقبال کا الہ آباد خطبہ۔"}, {"era": "1947-1948ء", "text_sd": "پاڪستان جو قيام؛ قائداعظم جي وفات.", "text_ur": "پاکستان کا قیام؛ قائداعظم کی وفات۔"}]};
HIST_DATA["special-forts-monuments"] = {"country": "Pakistan", "id": "forts-monuments", "kind": "topic", "name_sd": "قلعا ۽ يادگار", "name_ur": "قلعے اور یادگاریں", "region": "Pakistan", "sections_sd": [{"heading": "تعارف", "text": "پاڪستان ۾ مختلف دورن جا شاندار قلعا ۽ يادگار آهن، مغل فن تعمير کان وٺي ٽالپر ۽ سک دور تائين. انهن مان ڪيترائي يونيسڪو عالمي ورثو آهن. هيٺ سڀ کان اهم قلعن ۽ يادگارن جو اختصار ڏنو ويو آهي."}, {"heading": "روهتاس قلعو (پنجاب)", "text": "شير شاهه سوري 1541 ۾ تعمير ڪرايو. اهو شروعاتي مسلم فوجي فن تعمير جو شاندار مثال آهي، جنهن جون ديوارون 4 ڪلوميٽرن کان وڌيڪ ۽ 68 برج ۽ 12 دروازا آهن. شير شاهه جي وفات (1545) کان اڳ مڪمل نه ٿي سگهيو. 1997 ۾ يونيسڪو عالمي ورثو قرار ڏنو ويو."}, {"heading": "لاهور قلعو ۽ شالامار باغ (پنجاب)", "text": "17 صدي جون مغل فن تعمير جون شاندار مثالون. قلعي ۾ شيش محل ۽ نولکها جهڙيون عمارتون آهن. ٻئي 1981 ۾ گڏيل طور يونيسڪو عالمي ورثو قرار ڏنا ويا."}, {"heading": "بادشاهي مسجد (لاهور)", "text": "اورنگزيب 1673 ۾ تعمير ڪرائي. اهو مغل دور جي وڏي ۾ وڏي مسجدن مان هڪ آهي ۽ لاهور جي سڃاڻپ آهي. يونيسڪو جي عارضي فهرست ۾ شامل آهي."}, {"heading": "شاهجهاني مسجد (ٺٽو، سنڌ)", "text": "شاهجهان 1647 ۾ تعمير ڪرائي. پنهنجي شاندار ٽائلن جي ڪم ۽ گنبذن لاءِ مشهور آهي. يونيسڪو جي عارضي فهرست ۾ شامل آهي."}, {"heading": "مڪلي جا مقبرا (سنڌ)", "text": "10 ڪلوميٽرن تي پکڙيل دنيا جي وڏي ۾ وڏي قبرستانن مان هڪ. سنڌ جي حاڪمن، بزرگن ۽ عالمن جا شاندار مقبرا هتي آهن. 1981 ۾ يونيسڪو عالمي ورثو قرار ڏنو ويو."}, {"heading": "رني ڪوٽ قلعو (سنڌ)", "text": "سنڌ جي عظيم ديوار. ان جي باني بابت اختلاف آهي؛ ڪيترائي ذريعا ان کي ٽالپر دور (لڳ ڀڳ 1812) سان ڳنڍين ٿا. 1993 کان يونيسڪو جي عارضي فهرست ۾ آهي."}, {"heading": "ديراور قلعو (چولستان، پنجاب)", "text": "چولستان جي ريگستان ۾ واقع تاريخي قلعو، جيڪو ريگستاني قلعن جي سلسلي جو حصو آهي. يونيسڪو جي عارضي فهرست ۾ ديراور ۽ چولستان جا ريگستاني قلعا شامل آهن."}, {"heading": "عمرڪوٽ قلعو (سنڌ)", "text": "ٿرپارڪر واري علائقي ۾ تاريخي قلعو. روايت موجب مغل بادشاهه اڪبر 1542 ۾ عمرڪوٽ ۾ پيدا ٿيو هيو. يونيسڪو جي عارضي فهرست ۾ شامل آهي."}, {"heading": "بلتت قلعو (هنزه، گلگت بلتستان)", "text": "هنزه ۾ 700 سال کان وڌيڪ پراڻو قلعو، جيڪو هنزه جي ميرن جو گهر هيو. هاڻي عجائب گھر طور بحال ڪيو ويو آهي ۽ يونيسڪو جي عارضي فهرست ۾ شامل آهي."}], "sections_ur": [{"heading": "تعارف", "text": "پاکستان میں مختلف ادوار کے شاندار قلعے اور یادگاریں ہیں، مغل فن تعمیر سے لے کر ٹالپر اور سکھ دور تک۔ ان میں سے کئی یونیسکو عالمی ورثہ ہیں۔ ذیل میں سب سے اہم قلعوں اور یادگاروں کا خلاصہ دیا گیا ہے۔"}, {"heading": "روہتاس قلعہ (پنجاب)", "text": "شیر شاہ سوری نے 1541 میں تعمیر کرایا۔ یہ ابتدائی مسلم فوجی فن تعمیر کی شاندار مثال ہے، جس کی دیواریں 4 کلومیٹر سے زیادہ اور 68 برج اور 12 دروازے ہیں۔ شیر شاہ کی وفات (1545) سے پہلے مکمل نہ ہو سکا۔ 1997 میں یونیسکو عالمی ورثہ قرار دیا گیا۔"}, {"heading": "لاہور قلعہ اور شالامار باغ (پنجاب)", "text": "17ویں صدی کی مغل فن تعمیر کی شاندار مثالیں۔ قلعے میں شیش محل اور نولکھا جیسی عمارتیں ہیں۔ دونوں 1981 میں مشترکہ طور پر یونیسکو عالمی ورثہ قرار دیے گئے۔"}, {"heading": "بادشاہی مسجد (لاہور)", "text": "اورنگزیب نے 1673 میں تعمیر کرائی۔ یہ مغل دور کی بڑی مسجدوں میں سے ایک ہے اور لاہور کی پہچان ہے۔ یونیسکو کی عارضی فہرست میں شامل ہے۔"}, {"heading": "شاہجہانی مسجد (ٹھٹھہ، سندھ)", "text": "شاہجہان نے 1647 میں تعمیر کرائی۔ اپنے شاندار ٹائلوں کے کام اور گنبدوں کے لیے مشہور ہے۔ یونیسکو کی عارضی فہرست میں شامل ہے۔"}, {"heading": "مکلی کے مقبرے (سندھ)", "text": "10 کلومیٹر پر پھیلا دنیا کے بڑے قبرستانوں میں سے ایک۔ سندھ کے حکمرانوں، بزرگوں اور علما کے شاندار مقبرے یہاں ہیں۔ 1981 میں یونیسکو عالمی ورثہ قرار دیا گیا۔"}, {"heading": "رنی کوٹ قلعہ (سندھ)", "text": "سندھ کی عظیم دیوار۔ اس کے بانی کے بارے میں اختلاف ہے؛ کئی ذرائع اسے ٹالپر دور (تقریباً 1812) سے جوڑتے ہیں۔ 1993 سے یونیسکو کی عارضی فہرست میں ہے۔"}, {"heading": "دیراور قلعہ (چولستان، پنجاب)", "text": "چولستان کے ریگستان میں واقع تاریخی قلعہ، جو ریگستانی قلعوں کے سلسلے کا حصہ ہے۔ یونیسکو کی عارضی فہرست میں دیراور اور چولستان کے ریگستانی قلعے شامل ہیں۔"}, {"heading": "عمرکوٹ قلعہ (سندھ)", "text": "تھرپارکر کے علاقے میں تاریخی قلعہ۔ روایت کے مطابق مغل بادشاہ اکبر 1542 میں عمرکوٹ میں پیدا ہوا تھا۔ یونیسکو کی عارضی فہرست میں شامل ہے۔"}, {"heading": "بلتت قلعہ (ہنزہ، گلگت بلتستان)", "text": "ہنزہ میں 700 سال سے زیادہ پرانا قلعہ، جو ہنزہ کے میروں کا گھر تھا۔ اب عجائب گھر کے طور پر بحال کیا گیا ہے اور یونیسکو کی عارضی فہرست میں شامل ہے۔"}], "sources": [{"title": "Rohtas Fort — Wikipedia", "url": "https://en.wikipedia.org/wiki/Rohtas_Fort"}, {"title": "Lahore Fort and Shalamar Gardens — PID (Government of Pakistan)", "url": "https://pid.gov.pk/site/press_detail/29664"}, {"title": "The Ancient Forts of Pakistan: Derawar, Rohtas, Baltit & More — Soul of Pakistan", "url": "http://soulofpakistan.com/the-ancient-forts-of-pakistan-from-derawar-to-baltit/"}], "summary_sd": "پاڪستان جا اهم قلعا ۽ يادگار: روهتاس قلعو، لاهور قلعو ۽ شالامار باغ، بادشاهي مسجد، شاهجهاني مسجد، مڪلي جا مقبرا، رني ڪوٽ، ديراور، عمرڪوٽ ۽ بلتت قلعو. انهن مان ٽي يونيسڪو عالمي ورثو آهن ۽ باقي عارضي فهرست ۾ شامل آهن.", "summary_ur": "پاکستان کے اہم قلعے اور یادگاریں: روہتاس قلعہ، لاہور قلعہ اور شالامار باغ، بادشاہی مسجد، شاہجہانی مسجد، مکلی کے مقبرے، رنی کوٹ، دیراور، عمرکوٹ اور بلتت قلعہ۔ ان میں سے تین یونیسکو عالمی ورثہ ہیں اور باقی عارضی فہرست میں شامل ہیں۔", "timeline": [{"era": "1541ء", "text_sd": "روهتاس قلعي جي تعمير شروع ٿي.", "text_ur": "روہتاس قلعے کی تعمیر شروع ہوئی۔"}, {"era": "1647-1673ء", "text_sd": "شاهجهاني مسجد (1647) ۽ بادشاهي مسجد (1673) تعمير ٿيون.", "text_ur": "شاہجہانی مسجد (1647) اور بادشاہی مسجد (1673) تعمیر ہوئیں۔"}, {"era": "1981ء", "text_sd": "لاهور قلعو، شالامار باغ ۽ مڪلي يونيسڪو عالمي ورثو قرار.", "text_ur": "لاہور قلعہ، شالامار باغ اور مکلی یونیسکو عالمی ورثہ قرار۔"}, {"era": "1997ء", "text_sd": "روهتاس قلعو يونيسڪو عالمي ورثو قرار.", "text_ur": "روہتاس قلعہ یونیسکو عالمی ورثہ قرار۔"}]};
HIST_DATA["special-museums-archives"] = {"country": "Pakistan", "id": "museums-archives", "kind": "topic", "name_sd": "عجائب گھر ۽ آرڪائيو", "name_ur": "عجائب گھر اور آرکائیو", "region": "Pakistan", "sections_sd": [{"heading": "تعارف", "text": "پاڪستان ۾ ڪيترائي اهم عجائب گهر ۽ آرڪائيو آهن، جيڪي ملڪ جي هزارين سالن جي ورثي ۽ تاريخي دستاويزن کي محفوظ ڪن ٿا. انهن ۾ برطانوي دور جا عجائب گهر، ماڳن جا عجائب گهر ۽ قومي آرڪائيو شامل آهن. هيٺ اهم ترين ادارن جو اختصار ڏنو ويو آهي."}, {"heading": "لاهور عجائب گھر (1865)", "text": "1865 ۾ قائم ٿيو ۽ 1894 ۾ مال روڊ تي موجوده عمارت ۾ منتقل ٿيو. اهو پاڪستان جو سڀ کان وڏو عجائب گهر آهي، جنهن ۾ 60 هزار کان وڌيڪ شيون آهن: گنڌارا فن، مغل مصوري، سکن جا هٿيار ۽ وادي سنڌ جون شيون. رڊيارڊ ڪپلنگ جي ناول ڪم ۾ هن عجائب گهر جو ذڪر آهي."}, {"heading": "قومي عجائب گهر، ڪراچي (1950)", "text": "17 اپريل 1950 تي فريئر هال ۾ قائم ٿيو ۽ 1970 ۾ برنس گارڊن واري موجوده عمارت ۾ منتقل ٿيو. هتي پنج هزار سال پراڻي ٿهذيب کان تحريک پاڪستان تائين جون گيلريون آهن، جن ۾ قرآنن جا نادر نسخا به شامل آهن."}, {"heading": "ٽيڪسلا عجائب گھر (1918)", "text": "1918 ۾ قائم ٿيو؛ ان جي قيام ۾ آرڪيالاجيڪل سروي آف انڊيا جا سر جان مارشل اهم ڪردار ادا ڪيو. هتي گنڌارا ٻڌ فن جو پاڪستان ۾ سڀ کان مڪمل مجموعو آهي، جنهن ۾ مورتيون، سڪا ۽ ٿانو شامل آهن."}, {"heading": "موھن جو دڙو عجائب گھر (سنڌ)", "text": "کوٽيل ماڳ تي قائم عجائب گهر، جتي کوٽائي مان مليل مهرون، ٿانو، زيور ۽ مورتيون رکيل آهن. اهو سنڌو ماٿريءَ جي ٿهذيب جي روزمره زندگيءَ جي جهلڪ ڏيکاري ٿو."}, {"heading": "فقير خانه عجائب گھر (لاهور)", "text": "علائقي جو سڀ کان وڏو خانگي مجموعو، جيڪو فقير خاندان جو آهي. 1901 ۾ عوام لاءِ کوليو ويو. هتي هزارين مخطوطا، مصوريون، سڪا ۽ گنڌارا فن جا نمونا آهن."}, {"heading": "قومي آرڪائيو، اسلام آباد (1973)", "text": "8 ڊسمبر 1973 تي قائم ٿيو. اهو حڪومت پاڪستان جي تاريخي ريڪارڊ، سرڪاري دستاويز ۽ خانگي مجموعا محفوظ ڪري ٿو ۽ انٽرنيشنل ڪائونسل آن آرڪائيوز جو ميمبر آهي. ان جي عمارت 1988 ۾ مڪمل ٿي."}, {"heading": "صوبائي آرڪائيو", "text": "سنڌ آرڪائيو ڪراچي ۾ صوبي جي تاريخي ريڪارڊ محفوظ ڪري ٿو، جنهن ۾ ٽالپر دور جا دستاويز به شامل آهن. پنجاب آرڪائيو لاهور ۾ مغل، سک ۽ برطانوي دور جا ريڪارڊ رکي ٿو. اهي محققن لاءِ اهم ذريعا آهن."}, {"heading": "سٽيزنز آرڪائيو آف پاڪستان", "text": "ڪراچي ۾ قائم خانگي ادارو، جيڪو زباني تاريخ، تصويرون ۽ ذاتي دستاويز گڏ ڪري ٿو. اهو قومي عجائب گهر جي بهتريءَ لاءِ حڪومت سان گڏجي ڪم ڪري رهيو آهي."}], "sections_ur": [{"heading": "تعارف", "text": "پاکستان میں کئی اہم عجائب گھر اور آرکائیو ہیں، جو ملک کے ہزاروں سال کے ورثے اور تاریخی دستاویزات کو محفوظ کرتے ہیں۔ ان میں برطانوی دور کے عجائب گھر، مقامات کے عجائب گھر اور قومی آرکائیو شامل ہیں۔ ذیل میں اہم ترین اداروں کا خلاصہ دیا گیا ہے۔"}, {"heading": "لاہور عجائب گھر (1865)", "text": "1865 میں قائم ہوا اور 1894 میں مال روڈ پر موجودہ عمارت میں منتقل ہوا۔ یہ پاکستان کا سب سے بڑا عجائب گھر ہے، جس میں 60 ہزار سے زیادہ اشیاء ہیں: گندھارا فن، مغل مصوری، سکھوں کے ہتھیار اور وادی سندھ کی اشیاء۔ رڈیارڈ کپلنگ کے ناول کِم میں اس عجائب گھر کا ذکر ہے۔"}, {"heading": "قومی عجائب گھر، کراچی (1950)", "text": "17 اپریل 1950 کو فریئر ہال میں قائم ہوا اور 1970 میں برنس گارڈن والی موجودہ عمارت میں منتقل ہوا۔ یہاں پانچ ہزار سال پرانی تہذیب سے تحریک پاکستان تک کی گیلریاں ہیں، جن میں قرآن کے نادر نسخے بھی شامل ہیں۔"}, {"heading": "ٹیکسلا عجائب گھر (1918)", "text": "1918 میں قائم ہوا؛ اس کے قیام میں آرکیالوجیکل سروے آف انڈیا کے سر جان مارشل نے اہم کردار ادا کیا۔ یہاں گندھارا بدھ فن کا پاکستان میں سب سے مکمل مجموعہ ہے، جس میں مورتیاں، سکے اور برتن شامل ہیں۔"}, {"heading": "موہنجوداڑو عجائب گھر (سندھ)", "text": "کھدے ہوئے مقام پر قائم عجائب گھر، جہاں کھدائی سے ملی مہریں، برتن، زیور اور مورتیاں رکھی ہیں۔ یہ وادی سندھ کی تہذیب کی روزمرہ زندگی کی جھلک دکھاتا ہے۔"}, {"heading": "فقیر خانہ عجائب گھر (لاہور)", "text": "علاقے کا سب سے بڑا نجی مجموعہ، جو فقیر خاندان کا ہے۔ 1901 میں عوام کے لیے کھولا گیا۔ یہاں ہزاروں مخطوطات، مصوریاں، سکے اور گندھارا فن کے نمونے ہیں۔"}, {"heading": "قومی آرکائیو، اسلام آباد (1973)", "text": "8 دسمبر 1973 کو قائم ہوا۔ یہ حکومت پاکستان کے تاریخی ریکارڈ، سرکاری دستاویزات اور نجی مجموعے محفوظ کرتا ہے اور انٹرنیشنل کونسل آن آرکائیوز کا رکن ہے۔ اس کی عمارت 1988 میں مکمل ہوئی۔"}, {"heading": "صوبائی آرکائیو", "text": "سندھ آرکائیو کراچی میں صوبے کے تاریخی ریکارڈ محفوظ کرتا ہے، جن میں ٹالپر دور کی دستاویزات بھی شامل ہیں۔ پنجاب آرکائیو لاہور میں مغل، سکھ اور برطانوی دور کے ریکارڈ رکھتا ہے۔ یہ محققین کے لیے اہم ذرائع ہیں۔"}, {"heading": "سٹیزنز آرکائیو آف پاکستان", "text": "کراچی میں قائم نجی ادارہ، جو زبانی تاریخ، تصویریں اور ذاتی دستاویزات جمع کرتا ہے۔ یہ قومی عجائب گھر کی بہتری کے لیے حکومت کے ساتھ مل کر کام کر رہا ہے۔"}], "sources": [{"title": "Lahore Museum — Wikipedia", "url": "http://en.wikipedia.org/wiki/Lahore_Museum"}, {"title": "National Museum of Pakistan — Wikipedia", "url": "http://en.wikipedia.org/wiki/National_Museum_of_Pakistan"}, {"title": "National Archives of Pakistan — Wikipedia", "url": "https://en.wikipedia.org/wiki/National_Archives_of_Pakistan"}, {"title": "The Dolorous Case of Pakistan's Museums — Cultural Property News", "url": "https://culturalpropertynews.org/the-dolorous-case-of-pakistans-museums/"}], "summary_sd": "پاڪستان جا اهم عجائب گهر ۽ آرڪائيو: لاهور عجائب گهر (1865)، قومي عجائب گهر ڪراچي (1950)، ٽيڪسلا عجائب گهر (1918)، موھن جو دڙو عجائب گهر، فقير خانه، قومي آرڪائيو اسلام آباد (1973)، صوبائي آرڪائيو ۽ سٽيزنز آرڪائيو آف پاڪستان. هي ادارا ملڪ جي ورثي ۽ تاريخي دستاويزن جا محافظ آهن.", "summary_ur": "پاکستان کے اہم عجائب گھر اور آرکائیو: لاہور عجائب گھر (1865)، قومی عجائب گھر کراچی (1950)، ٹیکسلا عجائب گھر (1918)، موہنجوداڑو عجائب گھر، فقیر خانہ، قومی آرکائیو اسلام آباد (1973)، صوبائی آرکائیو اور سٹیزنز آرکائیو آف پاکستان۔ یہ ادارے ملک کے ورثے اور تاریخی دستاویزات کے محافظ ہیں۔", "timeline": [{"era": "1865ء", "text_sd": "لاهور عجائب گهر قائم ٿيو.", "text_ur": "لاہور عجائب گھر قائم ہوا۔"}, {"era": "1918ء", "text_sd": "ٽيڪسلا عجائب گهر قائم ٿيو.", "text_ur": "ٹیکسلا عجائب گھر قائم ہوا۔"}, {"era": "1950ء", "text_sd": "قومي عجائب گهر ڪراچي قائم ٿيو.", "text_ur": "قومی عجائب گھر کراچی قائم ہوا۔"}, {"era": "1973ء", "text_sd": "قومي آرڪائيو آف پاڪستان قائم ٿيو.", "text_ur": "قومی آرکائیو آف پاکستان قائم ہوا۔"}]};

HIST_DATA["pakistan-sindh-moro"] = {"country":"Pakistan","id":"moro","kind":"city","name_sd":"مورو","name_ur":"مورو","region":"Sindh","sections_sd":[{"heading":"نالي جو بنياد","text":"مورو جي تاريخ گهڻي پراڻي آهي. 'تحفة الڪرام' جي حوالي سان ٻڌايو وڃي ٿو ته ميان نصير محمد ڪلهوڙي جي دور ۾ هي 'مڪان مورو' نالي هڪ ننڍو ڳوٺ هو. قاضي نذير مورائي موجب شهر جو نالو هندستان جي قديم 'موريا' خاندان تي رکيو ويو، جڏهن ته مکڻ خان سهيتي جي راءِ — جنهن کي وڌيڪ قرين قياس سمجهيو وڃي ٿو — موجب 'مورو'، 'مڪان مورو' مان نڪتو آهي جنهن جي معنيٰ 'موريا جي رهڻ جي جاءِ' آهي ۽ هي نالو 'موريو فقير' جي نالي تي آهي."},{"heading":"قديم ۽ وچون دور","text":"ڪجهه تاريخي دستاويزن موجب مورو جي تاريخ اٺين صدي هجريءَ تائين وڃي ٿي. برطانوي دور کان اڳ سنڌ 'پرڳڻن' ۾ ورهايل هئي ۽ مورو 'ساهتي پرڳڻي' جو حصو هو. هي علائقو سومرا، سما، ارغون، ڪلهوڙا ۽ ٽالپر خاندانن هيٺ رهيو. 1843ع ۾ برطانيا ٽالپرن کي شڪست ڏئي سنڌ فتح ڪئي."},{"heading":"برطانوي دور","text":"اي. ايڇ. ايٽڪن جي سنڌ گزيٽيئر موجب مورو حيدرآباد ضلعي جي سب ڊويزن نوشهرو فيروز جي پنجن تعلقن ۾ شامل هو. 1912ع ۾ ضلعو نوابشاهه بڻيو ته مورو تعلقو ان ۾ شامل رهيو ۽ سب ڊويزن جو هيڊڪوارٽر مورو ۾ هو. هن دور ۾ روڊن، اسڪولن ۽ ڊسپينسرين جو ڄار وڇايو ويو."},{"heading":"پاڪستان ٺهڻ ۽ سياسي ڪردار","text":"1935ع ۾ مسلم ليگ جي ميمبرسازي شروع ٿي ته مورو سميت ڪيترن ئي شهرن ۾ يونٽ کليا. قاضي فيض محمد مورائي سنڌ مسلم ليگ ورڪنگ ڪميٽيءَ جا ميمبر بڻيا. جنوري ۽ ڊسمبر 1946ع جي چونڊن ۾ غلام رسول جٽوئي (مسلم ليگ) مورو-سڪرنڊ جي سيٽ کٽي. حاجي امام بخش خان جٽوئي 1920ع ۾ بمبئي ڪائونسل جا ميمبر چونڊيا ويا هئا. جٽوئي خاندان جو آبائي علائقو مورو تعلقي جو نيو جٽوئي آهي."},{"heading":"جديد مورو","text":"15 جنوري 1970ع تي مورو سب ڊويزن بڻي (تعلقو مورو ۽ سڪرنڊ)، 1978ع ۾ سڪرنڊ الڳ ٿيو ۽ 5 نومبر 1989ع تي ضلعو نوشهرو فيروز قائم ٿيو. اڄ مورو تعلقي ۾ چار روينيو سرڪل (مورو، ڪهڪت، ڏورو بهڻ، سهره) ۽ شهر ۾ 12 يونين ڪائونسل آهن. شهر قومي شاهراه N-5 تي سنڌ جي وچ ۾ آهي، سنڌو درياهه کان 12 ڪلوميٽر پري. معيشت زراعت تي ٻڌل آهي — ڪڻڪ، ڪمند، ڪپهه ۽ چانور اهم فصل آهن جن کي روهڙي ۽ نصرت واهن مان پاڻي ملي ٿو. ذوالفقار علي ڀٽي جي دور ۾ شروع ٿيل سنڌو درياهه تي 5 ڪلوميٽر ڊگهي پُل (جيڪا ضلعي کي دادو ۽ لاڙڪاڻي سان ڳنڍي ٿي) 1980ع واري ڏهاڪي جي وچ ۾ جنرل ضياءُ الحق افتتاح ڪيو. قديم ورثي ۾ ٽي قديم کنڊر (سريني جو ڪوٽ، ميران جو ڪوٽ، باگو ڏڙو)، نانگو مندر، 1926ع جون آبپاشي ريسٽ هائوسز ۽ نوآبادياتي دور جون عمارتون شامل آهن. مين بازار، شاهي بازار ۽ صرافه بازار واپاري مرڪز آهن."}],"sections_ur":[{"heading":"نام کی وجہ تسمیہ","text":"مورو کی تاریخ بہت پرانی ہے۔ تحفۃ الکرام کے حوالے سے بتایا جاتا ہے کہ میاں نصیر محمد کلہوڑو کے دور میں یہ 'مکان مورو' نامی ایک چھوٹا گاؤں تھا۔ قاضی نذیر مورائی کے مطابق شہر کا نام ہندوستان کے قدیم 'موریا' خاندان پر رکھا گیا، جبکہ مکھن خان سہتو کی رائے — جسے زیادہ قرین قیاس سمجھا جاتا ہے — کے مطابق 'مورو'، 'مکان مورو' سے نکلا ہے جس کے معنی 'موریا کے رہنے کی جگہ' ہیں اور یہ نام 'موریو فقیر' کے نام پر ہے۔"},{"heading":"قدیم اور وسطی دور","text":"بعض تاریخی دستاویزات کے مطابق مورو کی تاریخ آٹھویں صدی ہجری تک جاتی ہے۔ برطانوی دور سے پہلے سندھ 'پرگنوں' میں تقسیم تھا اور مورو 'ساہتی پرگنہ' کا حصہ تھا۔ یہ علاقہ سومرا، سمہ، ارغون، کلہوڑا اور ٹالپر خاندانوں کے زیر اثر رہا۔ 1843 میں برطانیہ نے ٹالپوروں کو شکست دے کر سندھ فتح کیا۔"},{"heading":"برطانوی دور","text":"ای۔ ایچ۔ ایٹکن کے سندھ گزٹیئر کے مطابق مورو حیدرآباد ضلع کی سب ڈویژن نوشہرو فیروز کے پانچ تعلقوں میں شامل تھا۔ 1912 میں ضلع نوابشاہ بنا تو مورو تعلقہ اس میں شامل رہا اور سب ڈویژن کا ہیڈکوارٹر مورو میں تھا۔ اس دور میں سڑکوں، اسکولوں اور ڈسپنسریوں کا جال بچھایا گیا۔"},{"heading":"قیام پاکستان اور سیاسی کردار","text":"1935 میں مسلم لیگ کی رکنیت سازی شروع ہوئی تو مورو سمیت کئی قصبوں میں یونٹیں کھلیں۔ قاضی فیض محمد مورائی سندھ مسلم لیگ ورکنگ کمیٹی کے رکن بنے۔ جنوری اور دسمبر 1946 کے انتخابات میں غلام رسول جتوئی (مسلم لیگ) نے مورو-سکرنڈ کی نشست جیتی۔ حاجی امام بخش خان جتوئی 1920 میں بمبئی کونسل کے رکن منتخب ہوئے تھے۔ جتوئی خاندان کا آبائی علاقہ مورو تعلقے کا نیو جتوئی ہے۔"},{"heading":"جدید مورو","text":"15 جنوری 1970 کو مورو سب ڈویژن بنی (تعلقہ مورو اور سکرنڈ)، 1978 میں سکرنڈ الگ ہوا اور 5 نومبر 1989 کو ضلع نوشہرو فیروز قائم ہوا۔ آج مورو تعلقے میں چار ریونیو سرکل (مورو، کہکت، ڈورو بہن، سہرہ) اور شہر میں 12 یونین کونسل ہیں۔ شہر قومی شاہراہ N-5 پر سندھ کے وسط میں ہے، دریائے سندھ سے 12 کلومیٹر دور۔ معیشت زراعت پر مبنی ہے — گندم، گنا، کپاس اور چاول اہم فصلیں ہیں جنہیں روہڑی اور نصرت نہروں سے پانی ملتا ہے۔ ذوالفقار علی بھٹو کے دور میں شروع ہونے والا دریائے سندھ پر 5 کلومیٹر طویل پل (جو ضلع کو دادو اور لاڑکانہ سے جوڑتا ہے) 1980 کی دہائی کے وسط میں جنرل ضیاء الحق نے افتتاح کیا۔ قدیم ورثے میں تین قدیم کھنڈر (سرینی جو کوٹ، میران جو کوٹ، باگو ڈڑو)، نانگا مندر، 1926 کی آبپاشی ریسٹ ہاؤسز اور نوآبادیاتی دور کی عمارتیں شامل ہیں۔ مین بازار، شاہی بازار اور صرافہ بازار تجارتی مراکز ہیں۔"}],"sources":[{"title":"Wikipedia — Moro, Pakistan","url":"https://en.wikipedia.org/wiki/Moro,_Pakistan"},{"title":"Scribd — Moro Taluka: Past and Present (Dr. Junaid Hamid Samoa)","url":"https://www.scribd.com/document/525663258/Moro-Tareekh-Ain-Saqaafat-Aslam-Abbasi"},{"title":"Graana — Exploring Moro, Sindh","url":"https://www.graana.com/blog/exploring-moro-sindh/"},{"title":"PBS Digital Library — Naushero Feroz District census (agriculture)","url":"https://digitallibrary.pbos.gov.pk/pdf/Naushero%20Feroz%20District%20%28%20Sukkur%20Division%29.pdf"},{"title":"Scribd — History of Naushahro Feroze District (Muslim League era)","url":"https://www.scribd.com/document/373958797/History-of-Naushahro-Feroze"},{"title":"Govt of Sindh — Master Plan of Naushahro Feroze (Talpur/British era)","url":"https://urban.sindh.gov.pk/files/DURPSP/Master-Plan-of-Naushahro-Feroze.pdf"}],"summary_sd":"مورو ضلعي نوشهرو فيروز، سنڌ جو سڀ کان وڏو شهر آهي. روايت موجب ان جو نالو 'مڪان مورو' مان نڪتو آهي ('موريا جي رهڻ جي جاءِ'). هي قومي شاهراه N-5 تي سنڌ جي وچ ۾ واقع آهي ۽ سنڌو درياهه کان 12 ڪلوميٽر پري آهي. 2023ع جي مردم شماريءَ موجب آبادي 142,685 آهي. 5 نومبر 1989ع تي ضلعو نوشهرو فيروز قائم ٿيو.","summary_ur":"مورو ضلع نوشہرو فیروز، سندھ کا سب سے بڑا شہر ہے۔ روایت کے مطابق اس کا نام 'مکان مورو' سے نکلا ہے ('موریا کے رہنے کی جگہ')۔ یہ قومی شاہراہ N-5 پر سندھ کے وسط میں واقع ہے اور دریائے سندھ سے 12 کلومیٹر دور ہے۔ 2023 کی مردم شماری کے مطابق آبادی 142,685 ہے۔ 5 نومبر 1989 کو ضلع نوشہرو فیروز قائم ہوا۔","timeline":[{"era":"قديم دور","text_sd":"اٺين صدي هجريءَ تائين تاريخي حوالا؛ 'مڪان مورو' ڳوٺ جو ذڪر.","text_ur":"آٹھویں صدی ہجری تک کے تاریخی حوالے؛ 'مکان مورو' گاؤں کا ذکر۔"},{"era":"برطانوي دور","text_sd":"ساهتي پرڳڻي جو حصو؛ پوءِ حيدرآباد ضلعي جو تعلقو.","text_ur":"ساہتی پرگنہ کا حصہ؛ بعد میں حیدرآباد ضلع کا تعلقہ۔"},{"era":"1912ع","text_sd":"ضلعو نوابشاهه بڻيو؛ مورو تعلقو ان ۾ شامل رهيو ۽ سب ڊويزن جو هيڊڪوارٽر مورو ۾ هو.","text_ur":"ضلع نوابشاہ بنا؛ مورو تعلقہ اس میں شامل رہا اور سب ڈویژن کا ہیڈکوارٹر مورو میں تھا۔"},{"era":"1946ع","text_sd":"غلام رسول جٽوئي مسلم ليگ طرفان مورو-سڪرنڊ سيٽ کٽي.","text_ur":"غلام رسول جتوئی مسلم لیگ کی طرف سے مورو-سکرنڈ نشست جیتے۔"},{"era":"1970ع","text_sd":"15 جنوري تي مورو سب ڊويزن بڻي (تعلقو مورو ۽ سڪرنڊ).","text_ur":"15 جنوری کو مورو سب ڈویژن بنی (تعلقہ مورو اور سکرنڈ)۔"},{"era":"1989ع","text_sd":"5 نومبر تي ضلعو نوشهرو فيروز قائم ٿيو.","text_ur":"5 نومبر کو ضلع نوشہرو فیروز قائم ہوا۔"},{"era":"اڄ","text_sd":"ضلعي جو سڀ کان وڏو شهر؛ 2023ع جي مردم شماريءَ ۾ آبادي 142,685.","text_ur":"ضلع کا سب سے بڑا شہر؛ 2023 کی مردم شماری میں آبادی 142,685۔"}]};
